import{_ as i,o as t,c as h,a5 as o}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-8-update-user/report3_spec.md","filePath":"feature/admin-management/3-10-8-update-user/report3_spec.md"}'),g={name:"feature/admin-management/3-10-8-update-user/report3_spec.md"};function l(a,n,r,s,u,c){return t(),h("div",null,[...n[0]||(n[0]=[o("<p><strong>3.10.8 Update User (Chỉnh Sửa Chi Tiết Người Dùng)</strong></p><p><strong>Function Trigger</strong></p><p>Bắt đầu khi Quản trị viên (ADMIN) chọn &quot;Chỉnh sửa&quot; từ menu người dùng hoặc trang chi tiết /admin/users/:id.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN. Quản trị viên hệ thống có quyền cập nhật thông tin tài khoản người dùng.</li><li><strong>Purpose</strong>: Cho phép Admin cập nhật thông tin hồ sơ (Họ tên, Số điện thoại, Vai trò, Trạng thái) của người dùng khi có yêu cầu hợp lệ.</li><li><strong>Interface</strong>: Màn hình Cập nhật Chi tiết Người dùng (SCR-ADM-08), gồm form chỉnh sửa thông tin, khung hiển thị thẻ phạt 30 ngày (chỉ đọc) và nút lưu thay đổi.</li><li><strong>Data Processing</strong>: Kiểm tra ADMIN, email bất biến, system role và lý do audit. Sửa trường hồ sơ được phép; quyền sở hữu Agency quản lý riêng. Lưu đổi gói cho kỳ thanh toán tiếp theo và vẫn yêu cầu thanh toán. Không đổi quota ngay, ghi đã thu tiền hoặc tạo doanh thu.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Màn hình Cập nhật Chi tiết Người dùng (SCR-ADM-08):</p><ul><li>Left/Header: Sidebar điều hướng Admin; Breadcrumb &quot;Admin / Quản lý Người dùng / Chỉnh sửa&quot;, tiêu đề &quot;Chỉnh sửa Tài khoản&quot; kèm User ID.</li><li>Center: Tên/điện thoại/bio/avatar được sửa, email chỉ đọc; system role ADMIN/USER; quyền Agency chỉ hiển thị ngữ cảnh. Hiện gói hiện tại, gói catalog yêu cầu, ngày hiệu lực kỳ sau và nhắc phải thanh toán. Bắt buộc lý do.</li><li>Buttons: Nút &quot;Lưu thay đổi&quot; (màu xanh), Nút &quot;Hủy bỏ / Quay lại&quot;.</li><li>Footer: Ghi chú kiểm toán: &quot;Mọi thay đổi vai trò hoặc thông tin người dùng đều được ghi lại trong Audit Log để phục vụ đối soát&quot;.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: userId, fullName (2–100 ký tự), role (ADMIN/USER), justification.</li><li><strong>Input optional</strong>: phoneNumber, bio, avatarUrl, requestedPlanId (catalog hiện có).</li><li><strong>System data</strong>: adminId, email bất biến, currentRole, currentPlan, nextBillingAt, pendingPlanChange và trạng thái thanh toán, updatedAt.</li><li><strong>Output</strong>: Hồ sơ người dùng sau khi cập nhật kèm mã HTTP 200 OK.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-19</strong>: Email chỉ đọc; API từ chối sửa email.</li><li><strong>BR-82</strong>: System role chỉ gồm ADMIN và USER. Quyền thành viên Agency/Workspace quản lý riêng. Mã gói lấy từ catalog subscription hiện có (hiện tại BASIC, PRO, ENTERPRISE), không tạo danh mục gói cứng khác.</li><li><strong>BR-83</strong>: Đổi quyền sở hữu Agency/Workspace dùng luồng thành viên riêng. Màn hình này không được xóa Owner cuối qua sửa system role; vẫn được sửa hồ sơ Owner duy nhất.</li><li><strong>BR-23</strong>: Owner duy nhất của Agency/Workspace vẫn được sửa hồ sơ, ghi strike, gắn cờ và khóa tài khoản 30 ngày sau xác nhận. Thành viên khác tiếp tục quyền hiện có; thao tác chỉ Owner được làm tạm dừng đến khi mở khóa. Không khóa cả Agency, không tự chuyển quyền sở hữu. Quyền Owner độc lập với system role.</li><li><strong>BR-35</strong>: Admin không hạ/sửa system role của Admin ngang hàng; giữ bảo vệ vai trò bản thân/ngang hàng hiện có.</li><li><strong>BR-60</strong>: Admin đổi gói có hiệu lực kỳ thanh toán tiếp theo và khách vẫn phải trả tiền qua subscription hiện có. Giữ quyền gói hiện tại đến biên kỳ. Chưa thanh toán không cấp quyền trả phí; thao tác đổi gói không tạo doanh thu hoặc hóa đơn đã trả.</li><li><strong>BR-16</strong>: Audit chênh lệch hồ sơ, role, gói yêu cầu, ngày hiệu lực và lý do riêng với sự kiện thanh toán thật.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Thiếu ADMIN → MSG39; không có đối tượng → MSG38; thiếu trường/lý do → MSG02.</li><li>Sửa email, system role không hỗ trợ hoặc gói ngoài catalog → từ chối.</li><li>Sửa role Admin ngang hàng hoặc đổi quyền sở hữu Agency qua form này → từ chối.</li><li>Sửa hồ sơ hợp lệ của Owner duy nhất → cho phép; cập nhật thành công → MSG26.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Tải hồ sơ, quyền Agency riêng, gói hiện tại và ngày kỳ thanh toán tiếp theo.</li><li>Admin sửa hồ sơ/system role được phép hoặc chọn gói kỳ sau, nhập lý do.</li><li>Kiểm tra bất biến email, bảo vệ role và giá trị catalog.</li><li>Lưu hồ sơ và gói chờ; không đổi quyền gói kỳ hiện tại.</li><li>Audit, hiển thị gói hiện tại/chờ cùng ngày hiệu lực và yêu cầu thanh toán.</li><li>Subscription hiện có áp dụng đổi gói kỳ sau chỉ sau khi thanh toán cần thiết thành công.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>1.a1: Không có user → MSG38; thiếu ADMIN → MSG39.</li><li>3.a1: Thiếu lý do hoặc sửa trường/role bị bảo vệ → từ chối, không cập nhật một phần.</li><li>6.a1: Thanh toán gia hạn lỗi → theo chính sách subscription hiện có; không cấp miễn phí hoặc ghi doanh thu giả.</li><li>6.a2: Chưa có kỳ tiếp theo xác định → qua luồng đăng ký subscription hiện có; không tự nâng gói miễn phí ngay.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Trường hồ sơ hợp lệ được cập nhật; form không sửa email và quyền sở hữu Agency.</li><li>Gói chờ lưu ngày kỳ sau và yêu cầu trả tiền; giữ quota hiện tại đến lúc đổi có hiệu lực.</li><li>Audit lưu thay đổi; doanh thu chỉ đổi theo sự kiện tài chính thật.</li></ul>",14)])])}const d=i(g,[["render",l]]);export{p as __pageData,d as default};
